script:
(function () {
  'use strict';
  // ---- Federal Direct Consolidation Loan rules (checked October 2026; sources below) ----------
  // Interest rate: the weighted average of the rates on the loans being consolidated, "rounded to
  //   the nearest higher one-eighth of one percent", with no cap for applications received on or
  //   after July 1, 2013 (34 CFR 685.202(a)(3)(i)(F); studentaid.gov consolidation page).
  // Only federal student loans can be consolidated; private loans stay as they are.
  // Repayment: a consolidation loan made on or after July 1, 2026 can be repaid only under the
  //   Tiered Standard plan or the Repayment Assistance Plan (RAP), and the borrower's other Direct
  //   Loans move to those plans too (One Big Beautiful Bill Act / ed.gov fact sheet). Tiered
  //   Standard: fixed payments, term set by the total outstanding Direct Loan principal:
  //   under $25,000 = 10 years; $25,000-$49,999 = 15; $50,000-$99,999 = 20; $100,000 or more = 25.
  //   RAP depends on income and family size and is not modelled.
  var ROUND_TO = 8;   // rate rounded up to the next 1/8 of a percentage point
  var TIERS = [{ below: 25000, years: 10 }, { below: 50000, years: 15 }, { below: 100000, years: 20 }, { below: Infinity, years: 25 }];
  // ---------------------------------------------------------------------------------------------
  // Maths: monthly interest = balance x rate / 12 (servicers accrue daily; monthly is a close
  //   estimate). Consolidation payment = B i / (1 - (1 + i)^-n), rounded up to the cent.
  // Plans compared, each simulated month by month (up to 50 years):
  //   1. Keep the loans, required payments only: each loan gets its own payment, nothing more.
  //   2. Keep the loans, avalanche: a fixed budget (all current payments + extra) pays every
  //      loan's payment, and whatever is left - including payments freed up by loans already
  //      repaid - goes to the highest-rate loan (ties: smaller balance first).
  //   3. Consolidate, required payments only: the new federal payment plus the private loans'.
  //   4. Consolidate and keep paying the same budget as plan 2, avalanche across the new loan and
  //      any private loans.
  // Verified (Node, scratchpad slc5/sc.test.js): $12,000 at 5.5% + $8,500 at 6.54% + $6,000 at
  //   7.05% -> weighted average 6.1845% -> 6.25%; exact eighths stay put (6.125% -> 6.125%) and
  //   6.126% -> 6.25%; $26,500 -> 15-year tier ($24,999.99 -> 10, $99,999 -> 20, $100,000 -> 25);
  //   $26,500 at 6.25% over 180 months = $227.22 (closed form $227.2171, rounded up), and the
  //   simulated loan ends at $0 in month 180;
  //   one $10,000 loan at 12% paying $222.45 -> 60 months; the avalanche total interest is never
  //   more than the required-payments plan's, and total paid = balances + interest (within a cent
  //   per loan) in every repaid plan (2,000 random loan sets);
  //   at 0% interest the avalanche finishes in ceil(total / budget) months.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var monthName = new Intl.DateTimeFormat('en-US', { month: 'short', year: 'numeric' });
  var ROWS = 5, MAX_MONTHS = 600;

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }
  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function consolidatedRate(loans) {
    var b = 0, w = 0;
    loans.forEach(function (l) { b += l.balance; w += l.balance * l.rate; });
    var avg = b > 0 ? w / b : 0;
    return { average: avg, rate: Math.ceil(avg * ROUND_TO - 1e-9) / ROUND_TO };
  }

  function tierYears(balance) {
    for (var k = 0; k < TIERS.length; k++) if (balance < TIERS[k].below) return TIERS[k].years;
    return 25;
  }

  function payment(principal, annualRate, n) {
    if (n <= 0 || principal <= 0) return 0;
    var i = annualRate / 1200;
    var p = i === 0 ? principal / n : principal * i / (1 - Math.pow(1 + i, -n));
    return Math.ceil(p * 100 - 1e-6) / 100;
  }

  // loans: [{balance, rate (%), pay}]; budget used only when rollover is true.
  function simulate(loans, budget, rollover) {
    var bal = loans.map(function (l) { return l.balance; }), done = loans.map(function () { return 0; });
    var interest = 0, paid = 0, years = [], m = 0, open = bal.some(function (b) { return b > 0.005; });
    var order = loans.map(function (l, k) { return k; }).sort(function (a, b) {
      return loans[b].rate - loans[a].rate || loans[a].balance - loans[b].balance;
    });
    while (open && m < MAX_MONTHS) {
      m++;
      var spent = 0, k;
      for (k = 0; k < loans.length; k++) {
        if (bal[k] <= 0.005) continue;
        var charge = bal[k] * loans[k].rate / 1200;
        interest += charge; bal[k] += charge;
        var p = Math.min(loans[k].pay, bal[k]);
        bal[k] -= p; spent += p;
      }
      if (rollover) {
        var left = budget - spent;
        for (var o = 0; o < order.length && left > 0.005; o++) {
          k = order[o];
          if (bal[k] <= 0.005) continue;
          var x = Math.min(left, bal[k]);
          bal[k] -= x; left -= x; spent += x;
        }
      }
      paid += spent;
      open = false;
      for (k = 0; k < loans.length; k++) {
        if (bal[k] <= 0.005) { if (!done[k] && loans[k].balance > 0) done[k] = m; bal[k] = 0; } else open = true;
      }
      if (m % 12 === 0 || !open) years.push(bal.reduce(function (s, b) { return s + b; }, 0));
    }
    return { months: open ? 0 : m, interest: interest, paid: paid, done: done, years: years };
  }

  function clearBody(id) {
    var body = el(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }
  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); });
    body.appendChild(tr);
  }
  function span(n) {
    if (!n) return 'Not within 50 years';
    var y = Math.floor(n / 12), mo = n % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' yr' : ' yrs'));
    if (mo) parts.push(mo + ' mo');
    return parts.join(' ');
  }
  function dateAfter(n) {
    var d = new Date();
    return monthName.format(new Date(d.getFullYear(), d.getMonth() + n, 1));
  }
  function pctText(v) { return (Math.round(v * 1000) / 1000) + '%'; }

  function update() {
    var loans = [], msg = '', extra = read('scExtra', true);
    for (var k = 1; k <= ROWS; k++) {
      var b = read('scBal' + k, true), r = read('scRate' + k, true), pay = read('scPay' + k, true);
      if (isNaN(b) || isNaN(r) || isNaN(pay)) { msg = 'Enter numbers only for loan ' + k + '.'; break; }
      if (b < 0 || r < 0 || r > 40 || pay < 0) { msg = 'Loan ' + k + ': use a balance and payment of 0 or more and a rate from 0% to 40%.'; break; }
      if (b === 0) continue;
      if (pay === 0) { msg = 'Enter the monthly payment for loan ' + k + '.'; break; }
      loans.push({ n: k, federal: el('scType' + k).value === 'federal', balance: b, rate: r, pay: pay });
    }
    if (!msg && isNaN(extra)) msg = 'Enter the extra monthly payment as a number.';
    else if (!msg && extra < 0) msg = 'The extra payment cannot be negative.';
    else if (!msg && loans.length === 0) msg = 'Enter the balance of at least one loan.';
    var error = el('scError');
    error.hidden = msg === '';
    if (msg) { error.textContent = msg; return; }

    var fed = loans.filter(function (l) { return l.federal; }), priv = loans.filter(function (l) { return !l.federal; });
    var current = loans.reduce(function (s, l) { return s + l.pay; }, 0), budget = current + extra;
    var fedBal = fed.reduce(function (s, l) { return s + l.balance; }, 0), fedPay = fed.reduce(function (s, l) { return s + l.pay; }, 0);
    var total = loans.reduce(function (s, l) { return s + l.balance; }, 0);
    var plans = [
      { name: 'Keep loans, required payments', first: current, sim: simulate(loans, current, false) },
      { name: 'Keep loans, avalanche', first: budget, sim: simulate(loans, budget, true) }
    ];
    var cons = null, consLoans = null;
    if (fed.length) {
      var cr = consolidatedRate(fed), years = tierYears(fedBal);
      cons = { average: cr.average, rate: cr.rate, years: years, pay: payment(fedBal, cr.rate, years * 12) };
      consLoans = [{ balance: fedBal, rate: cons.rate, pay: cons.pay }].concat(priv);
      plans.push({ name: 'Consolidate, required payments', first: cons.pay + (current - fedPay), sim: simulate(consLoans, 0, false) });
      plans.push({ name: 'Consolidate, same budget (avalanche)', first: Math.max(budget, cons.pay + current - fedPay),
                   sim: simulate(consLoans, Math.max(budget, cons.pay + current - fedPay), true) });
    }

    var none = el('scNoFederal');
    none.hidden = !!cons;
    if (cons) {
      setText('scConsRate', pctText(cons.rate));
      setText('scConsRateNote', 'Weighted average ' + pctText(Math.round(cons.average * 1000) / 1000) + ', rounded up to the next 1/8%');
      setText('scConsPay', money.format(cons.pay));
      setText('scConsPayNote', 'over ' + cons.years + ' years (Tiered Standard), vs ' + money.format(fedPay) + ' now for these loans');
    } else {
      setText('scConsRate', '–'); setText('scConsRateNote', 'No federal loans entered');
      setText('scConsPay', '–'); setText('scConsPayNote', '');
    }
    var av = plans[1].sim;
    setText('scAvTime', av.months ? span(av.months) : 'Not within 50 years');
    setText('scAvNote', av.months ? 'Debt-free around ' + dateAfter(av.months) + ', ' + money0.format(av.interest) + ' interest' : '');
    var best = null;
    plans.forEach(function (p) { if (p.sim.months && (best === null || p.sim.interest < best.sim.interest - 0.005)) best = p; });
    setText('scBest', best ? best.name : '–');
    setText('scBestNote', best ? money0.format(best.sim.interest) + ' total interest' : 'No plan repays the loans within 50 years.');
    setText('scTotal', money.format(total));
    setText('scFedBal', money.format(fedBal));
    setText('scPrivBal', money.format(total - fedBal));
    setText('scBudget', money.format(budget));
    setText('scPayChange', cons ? (cons.pay <= fedPay ? 'Lower by ' : 'Higher by ') + money.format(Math.abs(fedPay - cons.pay)) + ' a month' : '–');

    var cmp = clearBody('scCompare');
    plans.forEach(function (p) {
      addRow(cmp, [p.name, money.format(p.first), span(p.sim.months), p.sim.months ? money0.format(p.sim.interest) : '–',
                   p.sim.months ? money0.format(p.sim.paid) : '–']);
    });
    var lb = clearBody('scLoans');
    loans.forEach(function (l, i) {
      var inCons = '';
      if (cons) {
        if (l.federal) inCons = 'Joins the new loan, gone in ' + span(plans[3].sim.done[0]);
        else inCons = span(plans[3].sim.done[1 + priv.indexOf(l)]);
      }
      addRow(lb, ['Loan ' + l.n, l.federal ? 'Federal' : 'Private', money0.format(l.balance), pctText(l.rate),
                  span(av.done[i]), cons ? inCons : 'Not available']);
    });
    var yb = clearBody('scYears');
    var longest = Math.max.apply(null, plans.map(function (p) { return p.sim.years.length; }));
    for (var y = 0; y < longest; y++) {
      var cells = [String(y + 1)];
      for (var q = 0; q < 4; q++) {
        var s = plans[q] ? plans[q].sim.years : null;
        cells.push(!s ? '–' : money0.format(y < s.length ? s[y] : 0));
      }
      addRow(yb, cells);
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('scForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
